-- identity module: accounts, auth identities, devices, sessions, refresh tokens.
-- Owner: crates/identity. Spec: context/wiki/architecture/data-model.md and ADR-0004.
-- Conventions: UUIDv7 ids generated by the app, TIMESTAMPTZ, NOT NULL by default, enums as TEXT + CHECK,
-- tokens stored only as SHA-256 hashes (32 bytes), personal data encrypted by the app (BYTEA *_enc).

CREATE SCHEMA IF NOT EXISTS identity;
REVOKE ALL ON SCHEMA identity FROM PUBLIC;

CREATE TABLE identity.accounts (
    id                    UUID PRIMARY KEY,
    status                TEXT NOT NULL CHECK (status IN (
                              'pending_age', 'pending_profile', 'active',
                              'suspended', 'banned', 'deletion_pending')),
    -- AEAD ciphertext of the date of birth; set only once the age gate passes (DOB is locked).
    birth_date_enc        BYTEA NULL,
    -- Jurisdiction signals stored at sign-up: {"store": "US", "ip": "DE", "declared": "US"} (SR-24).
    region_signals        JSONB NOT NULL DEFAULT '{}'::jsonb,
    suspended_until       TIMESTAMPTZ NULL,
    deletion_requested_at TIMESTAMPTZ NULL,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX accounts_status_not_active ON identity.accounts (status) WHERE status <> 'active';

CREATE TABLE identity.auth_identities (
    id                      UUID PRIMARY KEY,
    account_id              UUID NOT NULL REFERENCES identity.accounts (id) ON DELETE CASCADE,
    provider                TEXT NOT NULL CHECK (provider IN ('apple', 'google', 'email')),
    -- Apple/Google `sub`, or the email hash for magic links. Never auto-linked across providers (AC-1.3).
    subject                 TEXT NOT NULL CHECK (length(subject) BETWEEN 1 AND 255),
    email                   TEXT NULL CHECK (email IS NULL OR length(email) <= 320),
    apple_refresh_token_enc BYTEA NULL,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider, subject)
);
CREATE INDEX auth_identities_account ON identity.auth_identities (account_id);

-- Device ids are generated by the client, so they are unique per account, not globally.
CREATE TABLE identity.devices (
    account_id    UUID NOT NULL REFERENCES identity.accounts (id) ON DELETE CASCADE,
    id            UUID NOT NULL,
    platform      TEXT NOT NULL CHECK (platform IN ('ios', 'android')),
    app_version   TEXT NOT NULL CHECK (length(app_version) BETWEEN 1 AND 32),
    attest_key_id TEXT NULL,
    last_seen_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (account_id, id)
);

-- One row per device sign-in = one refresh-token family (ADR-0004).
CREATE TABLE identity.sessions (
    id                  UUID PRIMARY KEY,
    account_id          UUID NOT NULL REFERENCES identity.accounts (id) ON DELETE CASCADE,
    access_token_hash   BYTEA NOT NULL UNIQUE CHECK (length(access_token_hash) = 32),
    access_expires_at   TIMESTAMPTZ NOT NULL,
    scope               TEXT NOT NULL CHECK (scope IN ('onboarding', 'full', 'widget', 'reauth', 'staff')),
    parent_session_id   UUID NULL REFERENCES identity.sessions (id) ON DELETE CASCADE,
    device_id           UUID NULL,
    client_label        TEXT NULL CHECK (client_label IS NULL OR length(client_label) <= 64),
    ip_country          TEXT NULL CHECK (ip_country IS NULL OR ip_country ~ '^[A-Z]{2}$'),
    idle_expires_at     TIMESTAMPTZ NOT NULL,
    absolute_expires_at TIMESTAMPTZ NOT NULL,
    last_seen_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at          TIMESTAMPTZ NULL,
    revoked_reason      TEXT NULL CHECK (revoked_reason IN (
                            'logout', 'logout_all', 'refresh_reuse', 'suspended',
                            'deleted', 'staff')),
    mfa_at              TIMESTAMPTZ NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL)),
    CHECK (idle_expires_at <= absolute_expires_at)
);
CREATE INDEX sessions_account_live ON identity.sessions (account_id) WHERE revoked_at IS NULL;
CREATE INDEX sessions_parent ON identity.sessions (parent_session_id) WHERE parent_session_id IS NOT NULL;

-- Single-use refresh tokens. Presenting a consumed one revokes the whole family (refresh_reuse).
CREATE TABLE identity.refresh_tokens (
    token_hash  BYTEA PRIMARY KEY CHECK (length(token_hash) = 32),
    session_id  UUID NOT NULL REFERENCES identity.sessions (id) ON DELETE CASCADE,
    generation  INT NOT NULL CHECK (generation >= 1),
    issued_at   TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ NULL,
    UNIQUE (session_id, generation)
);

-- Supabase exposes `anon` / `authenticated` roles through its Data API; app schemas must stay
-- invisible to them (ADR-0008). The roles do not exist in local/CI Postgres, hence the guard.
DO $$
DECLARE
    role_name TEXT;
BEGIN
    FOREACH role_name IN ARRAY ARRAY['anon', 'authenticated'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = role_name) THEN
            EXECUTE format('REVOKE ALL ON SCHEMA identity FROM %I', role_name);
            EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA identity FROM %I', role_name);
        END IF;
    END LOOP;
END
$$;
